    dups.add(key);
    if(f.hasAttribute('precision'))issues.push(`Fact ${f.localName} uses prohibited precision attribute.`);
    if(f.hasAttribute('scale'))issues.push(`Fact ${f.localName} uses a scale attribute.`);
